run_sql "
SELECT
    Origin,
    CRSDepTime,
    toHour(toDateTime('2026-06-15 ' || CRSDepTime)) as local_hour,
    if(Origin='ATL', local_hour - 4,
      if(Origin='ORD', local_hour - 5,
        if(Origin='DFW', local_hour - 5,
          if(Origin='DEN', local_hour - 6,
            local_hour - 7
          )
        )
      )
    ) as utc_hour
FROM aviation.flights
WHERE Cancelled = 0
  AND Origin IN ('ATL','ORD','DFW','DEN','LAX')
  AND CRSDepTime IS NOT NULL
  AND length(CRSDepTime) > 0
LIMIT 5
"

run_sql "
SELECT
    utc_hour,
    count() as dep_count
FROM (
    SELECT
        Origin,
        toInt32OrZero(substr(CRSDepTime, 1, 2)) -
        if(Origin='ATL', 4,
          if(Origin='ORD', 5,
            if(Origin='DFW', 5,
              if(Origin='DEN', 6, 7)
            )
          )
        ) as utc_hour
    FROM aviation.flights
    WHERE Cancelled = 0
      AND Origin IN ('ATL','ORD','DFW','DEN','LAX')
      AND CRSDepTime IS NOT NULL
      AND length(CRSDepTime) > 0
)
GROUP BY utc_hour
ORDER BY dep_count DESC
LIMIT 10
"

